CREATE TYPE "user_role" AS ENUM ('ADMIN', 'USER');
CREATE TYPE "transaction_status" AS ENUM ('DRAFT', 'COMPLETED', 'CANCELLED');
CREATE TYPE "transaction_type" AS ENUM ('STOCK_ADJUSTMENT_IN', 'STOCK_RELEASE', 'STOCK_RETURN');
CREATE TYPE "movement_purpose" AS ENUM ('ORIGINAL', 'CANCELLATION_REVERSAL');

CREATE TABLE "users" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "email" TEXT NOT NULL,
    "display_name" TEXT NOT NULL,
    "password_hash" TEXT NOT NULL,
    "role" "user_role" NOT NULL DEFAULT 'USER',
    "is_active" BOOLEAN NOT NULL DEFAULT true,
    "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP(3) NOT NULL
);

CREATE TABLE "models" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "model_name" TEXT NOT NULL,
    "description" TEXT,
    "is_active" BOOLEAN NOT NULL DEFAULT true,
    "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP(3) NOT NULL
);

CREATE TABLE "customers" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "customer_name" TEXT NOT NULL,
    "address" TEXT,
    "contact_person" TEXT,
    "contact_number" TEXT,
    "description" TEXT,
    "is_active" BOOLEAN NOT NULL DEFAULT true,
    "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP(3) NOT NULL
);

CREATE TABLE "service_tags" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "model_id" BIGINT NOT NULL,
    "customer_id" BIGINT,
    "service_tag" TEXT NOT NULL,
    "description" TEXT,
    "is_active" BOOLEAN NOT NULL DEFAULT true,
    "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP(3) NOT NULL
);

CREATE TABLE "devices" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "device_name" TEXT NOT NULL,
    "description" TEXT,
    "is_active" BOOLEAN NOT NULL DEFAULT true,
    "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP(3) NOT NULL
);

CREATE TABLE "device_details" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "device_id" BIGINT NOT NULL,
    "part_number" TEXT NOT NULL,
    "dpn" TEXT,
    "specification" TEXT NOT NULL,
    "description" TEXT,
    "is_active" BOOLEAN NOT NULL DEFAULT true,
    "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP(3) NOT NULL
);

CREATE TABLE "racks" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "rack_code" TEXT NOT NULL,
    "rack_name" TEXT NOT NULL,
    "description" TEXT,
    "is_active" BOOLEAN NOT NULL DEFAULT true,
    "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP(3) NOT NULL
);

CREATE TABLE "transaction_counters" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "transaction_type" "transaction_type" NOT NULL,
    "year_month" VARCHAR(6) NOT NULL,
    "last_number" INTEGER NOT NULL DEFAULT 0,
    "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP(3) NOT NULL
);

CREATE TABLE "stock_adjustment_ins" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "transaction_number" TEXT NOT NULL,
    "transaction_date" DATE NOT NULL,
    "customer_id" BIGINT,
    "notes" TEXT,
    "status" "transaction_status" NOT NULL DEFAULT 'DRAFT',
    "created_by" BIGINT NOT NULL,
    "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP(3) NOT NULL
);

CREATE TABLE "stock_adjustment_in_details" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "stock_adjustment_in_id" BIGINT NOT NULL,
    "device_detail_id" BIGINT NOT NULL,
    "rack_id" BIGINT NOT NULL,
    "quantity" INTEGER NOT NULL,
    "notes" TEXT,
    "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP(3) NOT NULL,
    CONSTRAINT "sai_quantity_positive" CHECK ("quantity" > 0)
);

CREATE TABLE "stock_releases" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "transaction_number" TEXT NOT NULL,
    "release_date" DATE NOT NULL,
    "engineer_name" TEXT NOT NULL,
    "customer_id" BIGINT NOT NULL,
    "model_id" BIGINT,
    "service_tag_id" BIGINT,
    "reference_number" TEXT,
    "notes" TEXT,
    "status" "transaction_status" NOT NULL DEFAULT 'DRAFT',
    "created_by" BIGINT NOT NULL,
    "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP(3) NOT NULL
);

CREATE TABLE "stock_release_details" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "stock_release_id" BIGINT NOT NULL,
    "device_detail_id" BIGINT NOT NULL,
    "rack_id" BIGINT NOT NULL,
    "released_quantity" INTEGER NOT NULL,
    "notes" TEXT,
    "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP(3) NOT NULL,
    CONSTRAINT "srl_quantity_positive" CHECK ("released_quantity" > 0)
);

CREATE TABLE "stock_returns" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "transaction_number" TEXT NOT NULL,
    "return_date" DATE NOT NULL,
    "stock_release_id" BIGINT NOT NULL,
    "notes" TEXT,
    "status" "transaction_status" NOT NULL DEFAULT 'DRAFT',
    "created_by" BIGINT NOT NULL,
    "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP(3) NOT NULL
);

CREATE TABLE "stock_return_details" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "stock_return_id" BIGINT NOT NULL,
    "stock_release_detail_id" BIGINT NOT NULL,
    "destination_rack_id" BIGINT NOT NULL,
    "return_quantity" INTEGER NOT NULL,
    "notes" TEXT,
    "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP(3) NOT NULL,
    CONSTRAINT "srt_quantity_positive" CHECK ("return_quantity" > 0)
);

CREATE TABLE "stock_movements" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "device_detail_id" BIGINT NOT NULL,
    "rack_id" BIGINT NOT NULL,
    "customer_id" BIGINT,
    "transaction_type" "transaction_type" NOT NULL,
    "transaction_id" BIGINT NOT NULL,
    "transaction_detail_id" BIGINT NOT NULL,
    "transaction_number" TEXT NOT NULL,
    "transaction_date" DATE NOT NULL,
    "engineer_name" TEXT,
    "quantity_in" INTEGER NOT NULL DEFAULT 0,
    "quantity_out" INTEGER NOT NULL DEFAULT 0,
    "movement_purpose" "movement_purpose" NOT NULL DEFAULT 'ORIGINAL',
    "reversal_of_id" BIGINT,
    "created_by" BIGINT NOT NULL,
    "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "stock_movement_one_side_positive" CHECK (
        ("quantity_in" > 0 AND "quantity_out" = 0)
        OR ("quantity_out" > 0 AND "quantity_in" = 0)
    ),
    CONSTRAINT "stock_movement_reversal_target_required" CHECK (
        ("movement_purpose" = 'ORIGINAL' AND "reversal_of_id" IS NULL)
        OR (
            "movement_purpose" = 'CANCELLATION_REVERSAL'
            AND "reversal_of_id" IS NOT NULL
        )
    )
);

