CREATE INDEX "stock_releases_model_id_idx" ON "stock_releases" ("model_id");
CREATE INDEX "stock_releases_service_tag_id_idx" ON "stock_releases" ("service_tag_id");
CREATE INDEX "stock_releases_status_date_idx" ON "stock_releases" ("status", "release_date");
CREATE INDEX "stock_releases_created_by_idx" ON "stock_releases" ("created_by");
CREATE INDEX "stock_release_details_header_id_idx" ON "stock_release_details" ("stock_release_id");
