CREATE FUNCTION "validate_stock_movement_reversal"()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
DECLARE
    original "stock_movements"%ROWTYPE;
BEGIN
    IF NEW."movement_purpose" <> 'CANCELLATION_REVERSAL' THEN
        RETURN NEW;
    END IF;

    SELECT *
    INTO original
    FROM "stock_movements"
    WHERE "id" = NEW."reversal_of_id"
    FOR KEY SHARE;

    IF NOT FOUND
       OR original."movement_purpose" <> 'ORIGINAL'
       OR original."reversal_of_id" IS NOT NULL THEN
        RAISE EXCEPTION 'stock movement reversal must reference an original movement'
            USING ERRCODE = '23514';
    END IF;

    IF ROW(
        NEW."device_detail_id",
        NEW."rack_id",
        NEW."customer_id",
        NEW."transaction_type",
        NEW."transaction_id",
        NEW."transaction_detail_id",
        NEW."transaction_number",
        NEW."transaction_date",
        NEW."engineer_name"
    ) IS DISTINCT FROM ROW(
        original."device_detail_id",
        original."rack_id",
        original."customer_id",
        original."transaction_type",
        original."transaction_id",
        original."transaction_detail_id",
        original."transaction_number",
        original."transaction_date",
        original."engineer_name"
    )
       OR NEW."quantity_in" <> original."quantity_out"
       OR NEW."quantity_out" <> original."quantity_in" THEN
        RAISE EXCEPTION 'stock movement reversal must be equal and opposite for the same stock and source dimensions'
            USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END;
$$;

CREATE TRIGGER "stock_movements_validate_reversal"
BEFORE INSERT ON "stock_movements"
FOR EACH ROW
EXECUTE FUNCTION "validate_stock_movement_reversal"();

CREATE FUNCTION "reject_stock_movement_mutation"()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
    RAISE EXCEPTION 'stock movements are immutable'
        USING ERRCODE = '55000';
END;
$$;

CREATE TRIGGER "stock_movements_reject_mutation"
BEFORE UPDATE OR DELETE ON "stock_movements"
FOR EACH ROW
EXECUTE FUNCTION "reject_stock_movement_mutation"();
